-- SELECT only. Save before apply. System catalogs and the migration history only (no app table rows).
-- 4천 자를 넘는 검사·정책 정의(예: app_profiles_view_prefs_check)는 snapshot 한 값 상한 8192자 때문에 해시·길이로 기록한다(10/31 dry-run run #160이 이 상한에서 멈춤).
select 'constraint' as kind,conrelid::regclass::text||'.'||conname as name,case when length(pg_get_constraintdef(oid))>4000 then 'md5:'||md5(pg_get_constraintdef(oid))||':length='||length(pg_get_constraintdef(oid)) else pg_get_constraintdef(oid) end as definition from pg_constraint where conrelid in (to_regclass('public.app_profiles'),to_regclass('public.app_documents'))
union all select 'policy',polrelid::regclass::text||'.'||polname,case when length(polcmd::text||polroles::text||polpermissive::text||coalesce(pg_get_expr(polqual,polrelid),'')||coalesce(pg_get_expr(polwithcheck,polrelid),''))>4000 then 'md5:'||md5(polcmd::text||polroles::text||polpermissive::text||coalesce(pg_get_expr(polqual,polrelid),'')||coalesce(pg_get_expr(polwithcheck,polrelid),''))||':length='||length(polcmd::text||polroles::text||polpermissive::text||coalesce(pg_get_expr(polqual,polrelid),'')||coalesce(pg_get_expr(polwithcheck,polrelid),'')) else polcmd::text||polroles::text||polpermissive::text||coalesce(pg_get_expr(polqual,polrelid),'')||coalesce(pg_get_expr(polwithcheck,polrelid),'') end from pg_policy where polrelid in (to_regclass('public.app_profiles'),to_regclass('public.app_documents'))
union all select 'owner RLS grants',relname,relowner::text||':'||relrowsecurity::text||':'||relforcerowsecurity::text||':'||coalesce(relacl::text,'none') from pg_class where oid in (to_regclass('public.app_profiles'),to_regclass('public.app_documents'))
union all select 'category function',p.oid::regprocedure::text,p.prosecdef::text||':'||coalesce(p.proconfig::text,'none')||':'||coalesce(p.proacl::text,'none')||':'||md5(p.prosrc)
  from pg_proc p where p.pronamespace='public'::regnamespace and p.proname like 'app_document_%categor%'
union all select 'owner check function',p.oid::regprocedure::text,p.prosecdef::text||':'||coalesce(p.proconfig::text,'none')||':'||md5(p.prosrc) from pg_proc p where p.pronamespace='private'::regnamespace and p.proname='app_is_workspace_owner'
union all select 'history',version,name from supabase_migrations.schema_migrations where version in ('20261018112943','20261031000000')
order by 1,2;
